#!/bin/zsh
# The registration and drift full case set: the same Swift tests as the gate, pointed at
# .build/pins-full/alignment (every vector at every noise level at 256 x 256, all the sizes, both drift stacks) through
# IMAGOKIT_PINS_FULL, regenerated by tools/registration-drift/pins.py. Run before a release; not
# part of CI (it needs the tools/requirements.txt environment to regenerate the pins). The tests print "BAND <label> <value> limit <limit> <case>"
# lines: the measured worst values, summarised at the end (limit -1: a near-tie case, held to its box instead).
#
#   python3 -I -B tools/registration-drift/pins.py   # when .build/pins-full is missing
#   tools/registration-drift/full-parity.sh
set -euo pipefail
cd "${0:A:h}/../.."
[[ -f .build/pins-full/alignment/registration-drift-pins.json ]] || {
  print -u2 "full-parity: .build/pins-full/alignment/registration-drift-pins.json is missing; run tools/registration-drift/pins.py first"; exit 1 }
log=.build/pins-full/alignment-full-parity.log
set +e
IMAGOKIT_BANDS=1 IMAGOKIT_PINS_FULL=$PWD/.build/pins-full swift test -c release --filter ImagoKitParityTests >$log 2>&1
rc=$?
set -e
grep -E "^(✘|✔ Test run|✘ Test run|Test run)" $log | tail -5 || true
python3 - $log <<'PY'
import collections, re, sys
worst = {}
count = collections.Counter()
for line in open(sys.argv[1]):
    if not line.startswith("BAND "):
        continue
    p = line.split()
    label = re.sub(r"\.(grid-constant|grid-wrap|constant|nearest|wrap|reflect|mirror)-o\d", "", p[1])
    label = re.sub(r"^(shift\.(f64|f32|public64|public32))\..*", r"\1", label)
    label = re.sub(r"^(fourier\.(f32|public64))\..*", r"\1", label)
    value, limit = float(p[2]), float(p[4])
    count[label] += 1
    if label not in worst or value > worst[label][0]:
        worst[label] = (value, limit, " ".join(p[5:]))
for k in sorted(worst):
    v, lim, case = worst[k]
    print("full-parity  %-32s n=%-5d worst %.3e  limit %s  (%s)" % (k, count[k], v, "near-tie box" if lim < 0 else "%.3e" % lim, case))
PY
print "full-parity: swift test exit $rc (log $log)"
exit $rc
